package org.springframework.samples.petclinic.acceptance;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

class HouseholdTest extends AcceptanceBase {

	@Test
	void householdIdIsTwelveHexCharactersOfSha256OverNormalizedLastNameAndPostcode() throws Exception {
		ObjectNode o = withPostcode(ownerNode());
		String lastName = o.get("lastName").asText();
		String householdId = fetchOwner(createOwnerOk(o)).get("householdId").asText();
		assertEquals(sha256hex(lastName.toLowerCase() + "|2000").substring(0, 12), householdId);
	}

	@Test
	void sameLastNameAndPostcodeWithoutSharesHouseholdIsRejected() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = withPostcode(ownerNode());
		a.put("lastName", lastName);
		createOwnerOk(a);

		ObjectNode b = withPostcode(ownerNode());
		b.put("lastName", lastName.toUpperCase());
		createOwner(b).andExpect(status().isConflict());
	}

	@Test
	void declaredHouseholdMemberIsCreatedAndNotFlaggedAsPossibleDuplicate() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = withPostcode(ownerNode());
		a.put("lastName", lastName);
		JsonNode first = fetchOwner(createOwnerOk(a));

		ObjectNode b = withPostcode(ownerNode());
		b.put("lastName", lastName);
		b.put("sharesHousehold", true);
		JsonNode member = fetchOwner(createOwnerOk(b));

		assertEquals(first.get("householdId").asText(), member.get("householdId").asText());
		assertFalse(member.get("possibleDuplicate").asBoolean());
		assertFalse(member.hasNonNull("possibleDuplicateOf"));
		assertEquals(2, member.get("householdSize").asInt());
	}
}

